const FAULT_CASES=[
{id:'not-serving',title:P('Impressions / spend zero','Zero impressions / spend'),source:['adstatus','rank'],facts:[P('Campaign report: 0 impressions, 0 spend.','Campaign report: zero impressions and spend.'),P('Account selected hai, lekin date range aur ad status abhi inspect nahi kiye.','The account is selected, but dates and ad status have not been inspected.'),P('Sirf budget barhanay ki recommendation dekh kar decision liya ja raha hai.','A budget recommendation is being used as the only evidence.')],q:P('Sab se pehla diagnostic action?','What is the first diagnostic action?'),options:[P('Blindly budget double kar do','Blindly double the budget'),P('Date/timezone, enabled status, start/end dates, policy/billing aur eligibility inspect karo','Inspect dates/timezone, enabled status, start/end dates, policy/billing and eligibility'),P('Naya duplicate account bana do','Create a duplicate account')],answer:1,why:P('Zero serving ki multiple causes hain. Status aur eligibility se problem narrow karo; phir keyword volume, targeting, Ad Rank aur bid constraints dekho.','Zero serving has several possible causes. Narrow the issue using status/eligibility before investigating demand, targeting, Ad Rank and bidding constraints.'),steps:[P('Correct account/campaign, date range, filters aur timezone confirm karo.','Confirm the account/campaign, dates, filters and timezone.'),P('Paused/ineligible/policy/billing issues ko exact status evidence se investigate karo.','Investigate paused/ineligible/policy/billing issues using exact status evidence.'),P('Eligible honay par demand, location/audience restrictions aur bid strategy diagnostics review karo.','If eligible, review demand, location/audience restrictions and bid-strategy diagnostics.')]},
{id:'disapproved',title:P('Ad disapproved','Ad disapproved'),source:['adstatus'],facts:[P('Ad disapproved hai. Specific policy reason available hai.','The ad is disapproved and a specific policy reason is available.'),P('Landing URL mobile par login wall dikhata hai.','The landing URL shows a login wall on mobile.'),P('Same ad ko copy karna destination ka issue fix nahi karta.','Copying the same ad does not fix its destination.')],q:P('Ab kya karo?','What should you do next?'),options:[P('Specific reason aur destination inspect karke issue fix karo; phir appropriate review/appeal process use karo','Inspect the reason/destination, fix the issue and use the appropriate review/appeal process'),P('Same problem ke saath 20 copies banao','Create 20 copies with the same problem'),P('Budget barhao','Increase budget')],answer:0,why:P('Policy reason ko evidence ke saath address karo. Review request approval ki guarantee nahi; circumvention se issue solve nahi hota.','Address the stated reason with evidence. A review request does not guarantee approval, and evasion does not resolve the issue.'),steps:[P('Exact disapproval reason aur linked policy parho.','Read the exact reason and linked policy.'),P('Ad claims, final URL, redirects aur mobile access ko test karo.','Test claims, the final URL, redirects and mobile access.'),P('Documented correction ke baad review request/appeal guidance follow karo.','After documenting the correction, follow review/appeal guidance.')]},
{id:'clicks-no-leads',title:P('Clicks hain, leads nahi','Clicks but no leads'),source:['websetup','tagtest'],facts:[P('200 relevant clicks; Ads conversions 0.','200 relevant clicks; zero Ads conversions.'),P('Mobile form par Submit dabane se error aata hai.','The mobile form errors after Submit.'),P('Backend mein bhi successful enquiries 0 hain.','The backend also contains zero successful enquiries.')],q:P('Evidence kis priority ko support karti hai?','Which priority does the evidence support?'),options:[P('Har keyword irrelevant declare kar do','Declare every keyword irrelevant'),P('Tracking count artificially barhao','Artificially increase reported conversions'),P('Form failure fix karo, phir valid/invalid/repeat aur mobile test dobara karo','Fix the form failure, then repeat valid/invalid/repeat and mobile tests')],answer:2,why:P('Is case mein actual customer journey broken hai. Sirf Ads reporting ya bids change karna backend ki zero enquiries explain/fix nahi karta.','Here the customer journey is broken. Reporting or bid changes do not fix zero successful backend enquiries.'),steps:[P('Reproduce error aur developer ko exact test evidence do.','Reproduce the error and provide precise evidence to the developer.'),P('Form success ko backend record aur event log se match karo.','Match form success with the backend record and event log.'),P('Fix ke baad traffic quality aur conversion-rate evidence review karo.','After the fix, review traffic quality and conversion-rate evidence.')]},
{id:'quality',title:P('Sasti leads, mehngay customers','Cheap leads, expensive customers'),source:['offline','terms'],facts:[P('Spend Rs 10,000; raw enquiries 20.','Spend Rs 10,000; 20 raw enquiries.'),P('Sirf 4 qualified; baqi out-of-area, spam ya jobs.','Only four are qualified; the others are out-of-area, spam or jobs.'),P('Raw CPL Rs 500; qualified CPL Rs 2,500.','Raw CPL is Rs 500; qualified CPL is Rs 2,500.')],q:P('Useful next action?','What is a useful next action?'),options:[P('Raw CPL low hai, foran scale karo','Raw CPL is low, so scale immediately'),P('CRM reasons, search intent aur location evidence se quality gap investigate karo','Investigate the quality gap using CRM reasons, search intent and location evidence'),P('Har enquiry ko qualified mark kar do','Mark every enquiry as qualified')],answer:1,why:P('10,000 ÷ 4 = 2,500. Raw lead price aur actual qualified/customer acquisition cost alag hain. Spam aur genuine sales follow-up gaps ko alag investigate karo.','10,000 ÷ 4 = 2,500. Raw lead price differs from qualified/customer acquisition cost. Investigate spam separately from genuine follow-up failures.'),steps:[P('Qualification rule aur CRM rejection reasons agree karo.','Agree qualification rules and CRM rejection reasons.'),P('Visible search terms, negative conflicts aur lead service areas inspect karo.','Inspect visible queries, negative conflicts and lead service areas.'),P('Consent/data requirements ke mutabiq qualified/offline feedback implementation plan verify karo.','Verify the qualified/offline feedback plan against applicable consent/data requirements.')]},
{id:'duplicates',title:P('3 orders, 6 conversions','Three orders, six conversions'),source:['transaction','goals'],facts:[P('Backend: 3 unique paid orders.','Backend: three unique paid orders.'),P('Ads direct Purchase aur GA4 imported Purchase: dono primary, 3 + 3.','Direct Ads Purchase and imported GA4 Purchase are both primary: 3 + 3.'),P('Same transaction IDs har action ke andar hain.','The same transaction IDs exist within each action.')],q:P('Sab se likely measurement issue?','What is the most likely measurement issue?'),options:[P('Ek outcome do separate biddable actions mein count ho raha hai; goal/action roles review karo','One outcome is counted in two biddable actions; review goal/action roles'),P('Business ne automatically 6 orders bech diye','The business automatically sold six orders'),P('Har order ki price double karo','Double every order price')],answer:0,why:P('Per-action transaction deduplication separate conversion actions ko merge nahi karti. Reporting dates, sources aur goal settings confirm karo; intentional separate actions ko blindly delete mat karo.','Per-action transaction deduplication does not merge separate conversion actions. Confirm dates, sources and goal settings; do not blindly delete intentionally separate actions.'),steps:[P('Conversion action ke naam/source ke hisaab se segment karo.','Segment by conversion action and source.'),P('Same outcome ko backend IDs/timestamps se reconcile karo.','Reconcile the outcome against backend IDs/timestamps.'),P('Intended bidding source aur secondary reporting role review karo; custom-goal exception check karo.','Review the intended bidding source and secondary reporting role, including the custom-goal exception.')]},
{id:'test-no-credit',title:P('Tag fire hua, Ads count nahi','Tag fired, no Ads credit'),source:['tagtest','lag'],facts:[P('Tag Assistant mein success event dikha.','Tag Assistant shows a success event.'),P('Test direct browser visit se kiya; ad interaction eligibility establish nahi.','The test used a direct visit; an eligible ad interaction is not established.'),P('Event firing, business success aur ad attribution teen separate checks hain.','Event firing, business success and ad attribution are separate checks.')],q:P('Sahi conclusion?','What is the correct conclusion?'),options:[P('Apna live ad baar baar click karo','Repeatedly click your live ad'),P('Tag firing ko guaranteed Ads credit samjho','Assume tag firing guarantees Ads credit'),P('Implementation, action IDs, source/consent aur attribution eligibility/delay separately verify karo','Verify implementation, action IDs, source/consent and attribution eligibility/delay separately')],answer:2,why:P('Sirf debug event fire honay se ad-attributed conversion prove nahi hoti. Apnay live ad ko click karna reliable testing method nahi.','A successful debug event alone does not establish an attributable conversion. Clicking your own ad is not a sound test method.'),steps:[P('Correct action ID/label, event parameters aur destination verify karo.','Verify the action ID/label, parameters and destination.'),P('Backend success aur applicable consent state ka test evidence rakho.','Keep evidence for backend success and applicable consent state.'),P('Reporting latency, attribution windows aur imported-source delay review karo.','Review reporting latency, attribution windows and import delay.')]},
{id:'value',title:P('Count sahi, revenue ghalat','Correct count, incorrect revenue'),source:['websetup','transaction'],facts:[P('Do paid orders: PKR 6,500 aur PKR 8,000.','Two paid orders: PKR 6,500 and PKR 8,000.'),P('Count 2 hai, lekin tag static PKR 100 per order bhejta hai.','The count is two, but the tag sends a static PKR 100 per order.'),P('Ads value PKR 200; backend total PKR 14,500.','Ads value is PKR 200; the backend total is PKR 14,500.')],q:P('Priority fix?','What is the priority fix?'),options:[P('ROAS target bohat high kar do','Set a very high ROAS target'),P('Dynamic order value/currency mapping fix aur multiple order amounts test karo','Fix dynamic value/currency mapping and test different order amounts'),P('Count ko 145 kar do','Change the count to 145')],answer:1,why:P('Count correctness se value correctness prove nahi hoti. Incorrect values value-based bidding aur ROAS ko misleading bana deti hain.','A correct count does not prove correct values. Incorrect values make value-based bidding and ROAS misleading.'),steps:[P('Paid-order source-of-truth total aur tax/shipping inclusion rule define karo.','Define the paid-order source-of-truth total and tax/shipping inclusion rule.'),P('Actual numeric value, currency aur transaction ID inspect karo.','Inspect the numeric value, currency and transaction ID.'),P('Different amounts aur repeat purchase event se regression test karo.','Regression-test different amounts and a repeated purchase event.')]},
{id:'lag',title:P('B2B sales abhi zero','B2B sales still zero'),source:['lag','window'],facts:[P('Sales cycle 30 days; report sirf pichlay 3 din ka hai.','The sales cycle is 30 days; the report covers only the last three days.'),P('6 enquiries, 2 verified qualified opportunities.','Six enquiries and two verified qualified opportunities.'),P('Tag aur form tests pass; won sales abhi pending hain.','Tag/form tests pass; won sales remain pending.')],q:P('Kya evidence support karti hai?','What does the evidence support?'),options:[P('Mature cohorts aur qualified pipeline inspect karo; zero recent won sales final failure ki proof nahi','Inspect mature cohorts and qualified pipeline; recent zero won sales do not prove final failure'),P('2 opportunities ko already won sale count karo','Count both opportunities as won sales'),P('Har roz saari settings change karo','Change all settings daily')],answer:0,why:P('Incomplete outcomes ko poor performance se alag karo. Spend anomalies aur broken tracking ke urgent checks phir bhi turant hotay hain.','Separate incomplete outcomes from poor performance. Urgent spend anomalies and broken tracking still require prompt checks.'),steps:[P('Conversion lag aur CRM stage definitions record karo.','Record conversion lag and CRM stage definitions.'),P('Comparable mature lead cohorts ka cost-to-qualified aur cost-to-won compare karo.','Compare cost-to-qualified and cost-to-won for comparable mature lead cohorts.'),P('Ek hypothesis, enough evidence aur rollback rule ke saath test plan banao.','Plan a test with one hypothesis, sufficient evidence and a rollback rule.')]}
];
let clinicTab='tracking',traceKind='form',faultIndex=0;
let traceConfig={rule:'click',dedupe:false,both:false,dynamic:false};
function evaluateTrace(kind,config){const trace=MEASUREMENT_TRACES[kind];if(!trace)return null;let count=0,value=0;const seen=new Set();const rows=trace.events.map(e=>{const eligible=config.rule==='outcome'?(kind==='call'?e.success&&e.seconds>=60:e.success):Boolean(e.click);const suppressed=eligible&&config.dedupe&&seen.has(e.id);if(eligible&&!suppressed)seen.add(e.id);const fires=eligible&&!suppressed?(config.both?2:1):0;const v=kind==='purchase'?fires*(config.dynamic?(e.value||0):100):0;count+=fires;value+=v;return{...e,fires,suppressed,value:v};});return{rows,count,value,expected:trace.expected,expectedValue:trace.value,correct:config.rule==='outcome'&&Boolean(config.dedupe)&&!config.both&&(kind!=='purchase'||Boolean(config.dynamic))&&count===trace.expected&&value===trace.value};}
function cleanClinic(v){const r={traces:[],answers:{},notes:{}};if(!v||typeof v!=='object')return r;r.traces=[...new Set((Array.isArray(v.traces)?v.traces:[]).filter(k=>Object.hasOwn(MEASUREMENT_TRACES,k)))];for(const f of FAULT_CASES){if(Number.isInteger(v.answers?.[f.id])&&v.answers[f.id]>=0&&v.answers[f.id]<f.options.length)r.answers[f.id]=v.answers[f.id];if(typeof v.notes?.[f.id]==='string')r.notes[f.id]=v.notes[f.id].slice(0,5000);}return r;}
function clinicSolved(){return FAULT_CASES.filter(f=>state.clinic.answers[f.id]===f.answer).length;}
function clinicPage(){return `${heading('SEARCH ADS · MEASURE, VERIFY, DIAGNOSE',U('Problem ko evidence se pakro.','Find the problem using evidence.'),U('3 measurement experiments aur 8 realistic fault cases. Pehle evidence, phir action.','Three measurement experiments and eight realistic fault cases. Evidence first, then action.'))}<div class="note">${U('Fictional teaching lab. Koi real Google tag fire nahi hota, koi call/place order nahi hota aur customer data send nahi hota. Counts aur deduplication simplified hain; actual attribution, consent aur conversion counting behavior implementation mein verify karo.','Fictional teaching lab. No real Google tags fire, no calls/orders occur and no customer data is sent. Counts and deduplication are simplified; verify attribution, consent and counting behavior in real implementation.')}</div><div class="tabs" style="margin-top:22px"><button data-clinic-tab="tracking" class="${clinicTab==='tracking'?'active':''}">${U('Tracking experiments','Tracking experiments')} · ${state.clinic.traces.length}/3</button><button data-clinic-tab="faults" class="${clinicTab==='faults'?'active':''}">${U('Troubleshooting desk','Troubleshooting desk')} · ${clinicSolved()}/8</button></div>${clinicTab==='tracking'?tracePage():faultPage()}${footer()}`;}
function tracePage(){const c=MEASUREMENT_TRACES[traceKind],r=evaluateTrace(traceKind,traceConfig);return `<div class="tabs">${Object.entries(MEASUREMENT_TRACES).map(([k,x])=>`<button data-trace-kind="${k}" class="${k===traceKind?'active':''}">${state.clinic.traces.includes(k)?'✓ ':''}${esc(t(x.title))}</button>`).join('')}</div><div class="card"><h2>${esc(t(c.title))}</h2><p>${esc(t(c.contract))}</p><div class="form-grid"><label class="field">${U('Event rule','Event rule')}<select id="trace-rule"><option value="click" ${traceConfig.rule==='click'?'selected':''}>${U('Button/link click','Button/link click')}</option><option value="outcome" ${traceConfig.rule==='outcome'?'selected':''}>${traceKind==='call'?U('Connected call ≥60 seconds','Connected call ≥60 seconds'):U('Confirmed success','Confirmed success')}</option></select></label><div><label class="sim-check"><input type="checkbox" id="trace-dedupe" ${traceConfig.dedupe?'checked':''}>${U('Repeat protection on','Repeat protection on')}</label><small>${U('Purchase: same action mein transaction ID. Form/call: simulated app-side event-ID guard.','Purchase: transaction ID within an action. Form/call: simulated app-side event-ID guard.')}</small><label class="sim-check" style="margin-top:14px"><input type="checkbox" id="trace-both" ${traceConfig.both?'checked':''}>${U('Same outcome ke 2 separate biddable sources/actions','Two separate biddable sources/actions for the same outcome')}</label>${traceKind==='purchase'?`<label class="sim-check" style="margin-top:14px"><input type="checkbox" id="trace-dynamic" ${traceConfig.dynamic?'checked':''}>${U('Actual order value bhejo (off: static PKR 100)','Send actual order value (off: static PKR 100)')}</label>`:''}</div></div><div class="metrics">${metric(U('Expected outcomes','Expected outcomes'),String(r.expected),'Fictional backend truth')}${metric(U('System ne kitne signals ginay','Emitted action events'),String(r.count),'Simplified teaching count')}${traceKind==='purchase'?metric('Emitted value',money(r.value),'Expected PKR 14,500'):metric(U('Difference','Difference'),String(r.count-r.expected),'Emitted minus expected')}</div><ol class="event-log">${r.rows.map(e=>`<li><span class="event-dot ${e.fires?'fired':''}"></span><div><b>${esc(t(e.label))}</b><small>${e.fires?`${e.fires} ${U('action event(s)','action event(s)')}${traceKind==='purchase'?' · '+money(e.value):''}`:e.suppressed?U('Repeat suppressed','Repeat suppressed'):U('Rule match nahi hui','Rule did not match')}</small></div></li>`).join('')}</ol><button class="btn" id="trace-verify">${U('Meri configuration check karo','Check my configuration')}</button><div id="trace-feedback" aria-live="polite"></div></div><section class="card" style="margin-top:22px"><h3>${U('Real implementation mein kya verify karna hai?','What must be verified in real implementation?')}</h3><ol class="steps">${c.checks.map(x=>`<li>${esc(t(x))}</li>`).join('')}<li>${U('Consent state aur data collection requirements ko implementation ke mutabiq test karo; is lab ka score consent compliance ki proof nahi.','Test consent state and data collection requirements for the implementation; a lab score does not establish compliance.')}</li></ol>${sourceLinks([...c.source,'consent'])}<div class="action-row"><button class="btn light" data-go="guides">${U('GTM implementation workbook','GTM implementation workbook')} →</button><button class="btn light" data-clinic-tab="faults">${U('Fault case solve karo','Solve a fault case')} →</button></div></section>`;}
function faultPage(){const f=FAULT_CASES[faultIndex],a=state.clinic.answers[f.id];return `<div class="journey-layout"><aside class="card journey-menu">${FAULT_CASES.map((x,i)=>`<button class="guide-step ${i===faultIndex?'active':''}" data-fault="${i}"><span>${state.clinic.answers[x.id]===x.answer?'✓':'○'}</span>${esc(t(x.title))}</button>`).join('')}</aside><article class="card"><div class="eyebrow">FICTIONAL CASE ${faultIndex+1} / 8</div><h2>${esc(t(f.title))}</h2><div class="example"><div class="label">${U('AVAILABLE EVIDENCE','AVAILABLE EVIDENCE')}</div><ul class="steps">${f.facts.map(x=>`<li>${esc(t(x))}</li>`).join('')}</ul></div><h3>${esc(t(f.q))}</h3><div class="quiz-options">${f.options.map((x,i)=>`<button class="option ${a===i?(i===f.answer?'correct':'wrong'):''}" data-fault-answer="${i}">${String.fromCharCode(65+i)}. ${esc(t(x))}</button>`).join('')}</div>${a!==undefined?`<div class="feedback ${a===f.answer?'':'error'}" role="status">${a===f.answer?'✓':U('Dobara dekho.','Reconsider.')} ${esc(t(f.why))}</div><h3 style="margin-top:25px">${U('Verification aur recovery plan','Verification and recovery plan')}</h3><ol class="steps">${f.steps.map(x=>`<li>${esc(t(x))}</li>`).join('')}</ol>`:''}<label class="field" style="margin-top:25px">${U('Apna next action + owner + proof + rollback likho','Write your next action + owner + proof + rollback')}<textarea id="fault-note" maxlength="5000" rows="5" placeholder="${U('Fictional practice data only','Fictional practice data only')}">${esc(state.clinic.notes[f.id]||'')}</textarea></label><small id="fault-save" role="status">${U('Notes browser mein autosave hotay hain; business correctness self-review hai.','Notes autosave in this browser; business correctness requires self-review.')}</small><div class="action-row"><button class="btn light" id="fault-export">${U('Recovery plan download','Download recovery plan')}</button><button class="btn" id="fault-next">${U('Agla case','Next case')} →</button></div><details class="source-details"><summary>${U('Official sources','Official sources')}</summary>${sourceLinks(f.source)}</details></article></div>`;}
function bindClinic(){$$('[data-clinic-tab]').forEach(b=>b.onclick=()=>{clinicTab=b.dataset.clinicTab;render();});$$('[data-trace-kind]').forEach(b=>b.onclick=()=>{traceKind=b.dataset.traceKind;render();});const rule=$('#trace-rule');if(rule)rule.onchange=e=>{traceConfig.rule=e.target.value;clinicRefresh();};for(const [id,key]of [['trace-dedupe','dedupe'],['trace-both','both'],['trace-dynamic','dynamic']]){const el=$('#'+id);if(el)el.onchange=e=>{traceConfig[key]=e.target.checked;clinicRefresh();};}const verify=$('#trace-verify');if(verify)verify.onclick=()=>{const r=evaluateTrace(traceKind,traceConfig);if(r.correct&&!state.clinic.traces.includes(traceKind)){state.clinic.traces.push(traceKind);save();}clinicRefresh();$('#trace-feedback').innerHTML=`<div class="feedback ${r.correct?'':'error'}" style="margin-top:15px">${r.correct?U('✓ Is fixture ki configuration sahi hai. Real tag, attribution aur CRM quality separately verify karni hai.','✓ Configuration matches this fixture. Real tags, attribution and CRM quality still require verification.'):U('Rule, repeat protection, source duplication aur purchase value review karo. Sirf same total aa jana same underlying event ki proof nahi.','Review the rule, repeat protection, duplicate sources and purchase value. A matching total alone does not prove the correct underlying event.')}</div>`;};$$('[data-fault]').forEach(b=>b.onclick=()=>{faultIndex=+b.dataset.fault;render();});$$('[data-fault-answer]').forEach(b=>b.onclick=()=>{state.clinic.answers[FAULT_CASES[faultIndex].id]=+b.dataset.faultAnswer;save();const y=window.scrollY;render();window.scrollTo(0,y);});const note=$('#fault-note');if(note)note.oninput=e=>{state.clinic.notes[FAULT_CASES[faultIndex].id]=e.target.value.slice(0,5000);save();$('#fault-save').textContent=storageOK?U('Saved in this browser','Saved in this browser'):U('Storage unavailable; plan download karo','Storage unavailable; download your plan');};const next=$('#fault-next');if(next)next.onclick=()=>{faultIndex=(faultIndex+1)%FAULT_CASES.length;render();};const ex=$('#fault-export');if(ex)ex.onclick=()=>{const f=FAULT_CASES[faultIndex];download('ads-asaan-'+f.id+'-recovery.json',{simulation:true,case:f.id,title:f.title[1],decisionCorrect:state.clinic.answers[f.id]===f.answer,notes:state.clinic.notes[f.id]||'',verificationSteps:f.steps.map(x=>x[1]),sources:f.source.map(k=>'https://support.google.com/google-ads/answer/'+SOURCES[k][1]+'?hl=en'),notice:'Fictional recovery exercise; does not verify a live account or authorize changes.'});};}

function clinicRefresh(){const y=window.scrollY;render();window.scrollTo(0,y);}
